    fields:[{label:'Fertigungstiefe erklären',prompt:'Definiert Fertigungstiefe. Erklärt am Bareiss-Beispiel in Absatz 2 dieser Akte, warum ein hoher Anteil eigener Herstellung sinnvoll sein kann.',min:70},{label:'Alternativen abwägen',prompt:'Vergleicht Eigenfertigung und Fremdbezug anhand von mindestens drei Kriterien. Prüft dabei eine Aussage aus Tonakte C3 an den Textblättern. Erklärt Ursache und Wirkung statt nur Stichworte aufzuzählen.',min:100},{label:'Empfehlung mit Bedingung',prompt:'Empfehlt für 100.000 Hüllen eine Variante. Bezieht die fiktive Rechnung und ein qualitatives Kriterium ein. Wann würdet ihr anders entscheiden?',min:90}],
